// File was generated by Claude.
// Randomized test for the 5R solver (base + planar 3R + wrist roll), arm5R_bnpr::inverse.
//
// Targets come from random joint angles via forward kinematics, so they are reachable by
// construction. From the resulting tool pose the test takes
//   - the tool position          -> target
//   - the tool x-axis            -> x_target
//   - the approach angle theta   (tool z-axis: 0 = pointing straight down, tilted within the
//                                 arm's plane towards the target for theta > 0)
// For every returned solution it runs the forward kinematics again and checks
//   1. the tool position equals the target,
//   2. the tool z-axis has the requested approach angle within that solution's arm plane,
//   3. the tool x-axis is x_target (or -x_target for flipped solutions) projected onto the plane
//      perpendicular to the tool z-axis.
// In addition, one of the solutions must reproduce the original pose exactly: position,
// tool x-axis and tool z-axis.
// Joint positions for the elbow check come from prefix(at<K>) / prefix_tool(at<K>).
// Targets close to the base axis are skipped (see below).

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <numbers>
#include <random>
#include "kinematics/analytic/base+3planar+roll.hpp"
#include "kinematics/general.hpp"

using namespace kinematics;
using arm5R_bnpr::Arm;
using arm5R_bnpr::Flags;
using arm5R_bnpr::Tool;

static int failures = 0;

struct Vec { double x, y, z; };
static Vec operator-(Vec a, Vec b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
static Vec operator*(double s, Vec a) { return {s * a.x, s * a.y, s * a.z}; }
static double dot(Vec a, Vec b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
static double norm(Vec a) { return std::sqrt(dot(a, a)); }

template<std::floating_point T>
static Vec column(const linalg::Matrix<T, 4, 4>& m, std::size_t col)
{
    return {double(m[1, col]), double(m[2, col]), double(m[3, col])};
}

// origin of joint K's frame (on joint K's axis) for the first K angles
template<std::size_t K, std::floating_point T>
static Vec joint_position(const Arm<T>& arm, const std::array<T, 5>& phi)
{
    std::array<T, K> p{};
    for (std::size_t i = 0; i < K; ++i) p[i] = phi[i];
    return column(forward(p, arm.prefix(at<K>), arm.prefix_tool(at<K>)), 0);
}

// approach angle of tool z-axis a within the arm plane with horizontal direction e (= base angle),
// oriented towards the target
static double approach_angle(Vec a, double phi0, Vec target)
{
    const Vec e{std::cos(phi0), std::sin(phi0), 0.0};
    const double towards = dot(target, e) >= 0 ? 1.0 : -1.0;
    return std::atan2(towards * dot(a, e), -a.z);
}

template<std::floating_point T>
void test_random(int n, double tol, double conv_tol, const char* label)
{
    std::mt19937 rng(11);
    std::uniform_real_distribution<double> uni(0.0, 1.0);
    const double pi = std::numbers::pi;

    int samples = 0, checked = 0, not_found = 0, bad = 0, vertical = 0;
    double max_pos = 0, max_z = 0, max_x = 0;
    auto fail = [&](const char* what, int i) { if (++bad <= 8) std::printf("  %s sample %d: %s\n", label, i, what); };

    for (int i = 0; i < n; ++i) {
        // random geometry: link lengths, small lateral offsets, sometimes a base height,
        // roll link with offsets, tool with axial length and sometimes a radial offset
        const T h = T(uni(rng) < 0.5 ? 0.0 : 0.5 * uni(rng));
        const T R1 = T(0.5 + 2.0 * uni(rng)), R2 = T(0.5 + 2.0 * uni(rng));
        const T roll_cn = T(uni(rng) < 0.5 ? 0.0 : 0.1 * uni(rng));
        const T roll_ra = T(0.05 + 0.3 * uni(rng));
        const std::array<T, 3> off{T(uni(rng) < 0.5 ? 0.0 : 0.1 * uni(rng)),
                                   T(uni(rng) < 0.5 ? 0.0 : 0.1 * uni(rng)), T(0)};
        const Arm<T> arm({T(0), T(0), R1, R2, roll_cn}, {h, off[0], off[1], off[2], roll_ra});
        const Tool<T> tool(T(0.05 + 0.2 * uni(rng)), T(uni(rng) < 0.5 ? 0.0 : 0.05 * uni(rng)));
        const double scale = double(h + R1 + R2 + roll_cn + roll_ra + off[0] + off[1]
                                    + tool.translation()[0] + tool.translation()[2]);

        // random configuration; in a quarter of the samples the approach is vertical (closed form)
        std::array<T, 5> phi{};
        for (auto& p : phi) p = T(-pi + 2 * pi * uni(rng));
        const bool want_vertical = uni(rng) < 0.25;
        if (want_vertical) phi[3] = T(-double(phi[1]) - double(phi[2]));

        // the solver keeps only configurations with the elbow not below the shoulder
        if (joint_position<2>(arm, phi).z < joint_position<1>(arm, phi).z) continue;

        const auto pose = forward(phi, arm, tool);
        const Vec target = column(pose, 0), x0 = column(pose, 1), z0 = column(pose, 3);
        // Close to the base axis "tilted towards the target" becomes ambiguous (the roll-axis point
        // and the tool point can lie on different sides of the base axis), and the fixed-point
        // iteration converges slowly. Keep targets well away from it.
        const double near_axis = 2.0 * double(off[0] + off[1] + roll_cn + roll_ra
                                              + tool.translation()[0] + tool.translation()[2]);
        if (std::hypot(target.x, target.y) <= near_axis) continue;

        double theta = approach_angle(z0, double(phi[0]), target);
        if (want_vertical && std::abs(theta) < 1e-9) { theta = 0.0; ++vertical; }
        ++samples;

        linalg::Vector<T, 3> tgt, xt;
        tgt[0] = T(target.x); tgt[1] = T(target.y); tgt[2] = T(target.z);
        xt[0] = T(x0.x); xt[1] = T(x0.y); xt[2] = T(x0.z);
        const auto sols = arm5R_bnpr::inverse(tgt, theta, xt, arm, tool, 1.0, conv_tol, 50);

        // Near full stretch or fold the problem is ill-conditioned; allow a larger error there.
        // Close to full stretch the iterated roll-axis point can also land just outside the
        // reachable range, so the original pose may be missing there.
        const double p2 = std::remainder(double(phi[2]), 2 * pi);
        const bool near_singular = std::abs(p2) < 0.06 || std::abs(std::abs(p2) - pi) < 0.06;
        const double pos_tol = tol * (near_singular ? 100.0 : 1.0);

        bool found = false;
        for (const auto& slot : sols) {
            if (!slot) continue;
            ++checked;
            const auto& ang = slot->angles();
            const auto m = forward(ang, arm, tool);
            const Vec p = column(m, 0), x = column(m, 1), z = column(m, 3);

            // 1. position
            const double e_pos = norm(p - target) / scale;
            // 2. approach angle within this solution's arm plane
            const double e_z = std::abs(std::remainder(approach_angle(z, double(ang[0]), target) - theta, 2 * pi));
            // 3. tool x-axis = projection of (+-) x_target onto the plane perpendicular to z
            const double sgn = slot->flags()[Flags::tool_flip_i] ? -1.0 : 1.0;
            const Vec k = sgn * x0;
            const Vec proj = k - dot(k, z) * z;
            const double e_x = norm(x - (1.0 / norm(proj)) * proj);

            max_pos = std::max(max_pos, e_pos);
            max_z = std::max(max_z, e_z);
            max_x = std::max(max_x, e_x);
            if (!(e_pos <= pos_tol))  fail("tool position misses the target", i);
            if (!(e_z <= tol * 100))  fail("tool z-axis has the wrong approach angle", i);
            if (!(e_x <= tol * 100))  fail("tool x-axis is not the projected x_target", i);

            // the original pose: same position, x-axis and z-axis
            if (!slot->flags()[Flags::tool_flip_i]
                && norm(p - target) / scale < 1e-3 && norm(x - x0) < 1e-3 && norm(z - z0) < 1e-3)
                found = true;
        }
        if (!found && !near_singular) {
            ++not_found;
            fail("original pose not among the solutions", i);
        }
    }
    std::printf("%s: %d samples (%d vertical), %d solutions checked, %d originals not found, %d failures,\n"
                "    max position error %.3g, max approach angle error %.3g, max x-axis error %.3g\n",
                label, samples, vertical, checked, not_found, bad, max_pos, max_z, max_x);
    if (bad) ++failures;
}

int main()
{
    test_random<double>(20000, 1e-11, 1e-13, "double");
    test_random<float>(20000, 1e-5, 1e-6, "float");
    if (failures == 0) std::printf("All 5R arm kinematics tests passed\n");
    return failures == 0 ? 0 : 1;
}